WITH scored AS (SELECT *, MIN(unit_price) OVER (PARTITION BY order_id) AS order_id_min_unit_price, LEAD(quantity, 1, 0) OVER (PARTITION BY product_id ORDER BY quantity, id) AS next_quantity, RANK() OVER (PARTITION BY product_id ORDER BY unit_price DESC) AS unit_price_rank, CORR(unit_price, quantity) OVER (PARTITION BY order_id) AS corr_unit_price_quantity FROM order_items), joined AS (SELECT src.id, src.order_id, src.product_id, src.unit_price, src.order_id_min_unit_price, src.next_quantity, src.unit_price_rank, src.corr_unit_price_quantity, p.brand, p.cost, p.launch_date FROM scored src INNER JOIN products p ON src.product_id <=> p.id WHERE p.stock_qty < 245), with_windows AS (SELECT *, SUM(order_id_min_unit_price) OVER w_recent AS cumulative_order_id_min_unit_price, MIN(next_quantity) OVER w_grp AS product_id_min_next_quantity, CUME_DIST() OVER (PARTITION BY order_id ORDER BY cost NULLS LAST) AS cost_cume_dist FROM joined WINDOW w_recent AS (PARTITION BY product_id ORDER BY launch_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_grp AS (PARTITION BY product_id)), joined_order_items AS (SELECT src.id, src.product_id, src.unit_price, src.order_id_min_unit_price, src.unit_price_rank, src.cost, src.launch_date, src.product_id_min_next_quantity, b.brand AS product_brand, b.cost AS product_cost FROM with_windows src LEFT JOIN products b ON src.product_id <=> b.id) SELECT id, product_id, unit_price_rank, cost, product_cost, ROUND(unit_price / SUM(unit_price) OVER (PARTITION BY product_brand), 4) AS unit_price_share, ROUND(unit_price / SUM(unit_price) OVER (PARTITION BY product_brand), 4) AS unit_price_share_2, COUNT(product_id_min_next_quantity) OVER (PARTITION BY product_id) AS product_id_count_product_id_min_next_quantity, AVG(product_id_min_next_quantity) OVER (PARTITION BY product_id ORDER BY launch_date, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS product_id_min_next_quantity_avg_6_prior FROM joined_order_items
